15	// pathBarLabel prefixes the target field in the bar.
16	const pathBarLabel = "Target › "
17	
18	// pathColumns describes the Path column. Plain text in Cell, colour in Style
19	// (Rule 122). A silent hop is dim, never red: it is not a failure.
20	func pathColumns() []datatable.Column[pathStep] {
21		hop := datatable.Column[pathStep]{
22			Title: "Hop", Sizing: datatable.SizingFixed, MinWidth: 3,
23			Cell: pathStep.hopCell,
24		}
25		step := datatable.Column[pathStep]{
26			Title: "Step", Sizing: datatable.SizingFixed, MinWidth: 11,
27			Cell:  pathStep.stepCell,
28			Style: pathStepStyle,
29		}
30		address := datatable.Column[pathStep]{
31			Title: "Address", Sizing: datatable.SizingContent, MinWidth: 15, Flex: 1,
32			Cell:  pathStep.addressCell,
33			Style: pathAddressStyle,
34		}
35		rtt := datatable.Column[pathStep]{
36			Title: "RTT", Sizing: datatable.SizingFixed, MinWidth: 9,
37			Cell:  pathStep.rttCell,
38			Style: pathRTTStyle,
39		}
40		return []datatable.Column[pathStep]{hop, step, address, rtt}
41	}
42	
43	func pathStepStyle(s pathStep) lipgloss.Style {
44		if s.Kind == stepNoResponse {
45			return theme.DimStyle
46		}
47		if s.Kind != stepHop {
48			return lipgloss.Style{}
49		}
50		switch s.Hop.Kind {
51		case nettrace.HopSilent, nettrace.HopUnresolved:
52			return theme.DimStyle
53		case nettrace.HopError:
54			return theme.SeverityTextStyle("MEDIUM")
55		}
56		return lipgloss.Style{}
57	}
58	
59	func pathAddressStyle(s pathStep) lipgloss.Style {
60		switch s.Kind {
61		case stepTrace, stepEngine:
62			return theme.DimStyle
63		case stepNetwork:
64			if s.Container.dimNetwork() {
65				return theme.DimStyle
66			}
67		case stepHop:
68			if !s.Hop.Addr.IsValid() {
69				return theme.DimStyle
70			}
71		case stepInterface, stepGateway:
72			if c := s.addressCell(); c == routeUndetermined || c == gatewayDirect || c == gatewayNone {
73				return theme.DimStyle
74			}
75		}
76		return lipgloss.Style{}
77	}
78	
79	func pathRTTStyle(s pathStep) lipgloss.Style {
80		if s.Kind == stepNoResponse || (s.Kind == stepHop && s.Hop.RTT <= 0) {
81			return theme.DimStyle
82		}
83		return lipgloss.Style{}
84	}
85	
86	// view renders the table; the body is never replaced (Rule 139). The open
87	// selector is drawn over it.
88	func (pm *PathModel) view() string {
89		if pm.pickerOpen() {
90			return pm.viewWithPicker(pm.table.View())
91		}
92		return pm.table.View()
93	}
94	
95	// barView is the target field in its frame, two lines in every state.
96	func (pm *PathModel) barView(width int) string {
97		return components.BarFrame(width, theme.KeyStyle.Render(pathBarLabel)+pm.input.View())
98	}
99	
100	// statusLine is derived on every frame (Rule 128).
101	func (pm *PathModel) statusLine() components.Status {
102		if pm.errText != "" {
103			return components.Status{Text: pm.errText, Level: components.LevelError}
104		}
105		if pm.pickerOpen() {
106			return pm.pickerStatus()
107		}
108		if pm.state != pathRunning {
109			if a := pm.launchable(); !a.Enabled() {
110				// The platform cannot trace: say so up front, derived every frame.
111				return components.Status{Text: a.Reason, Level: components.LevelWarning}
112			}
113			return components.Status{}
114		}
115		host := pm.target.Host
116		n := pm.hopCount()
117		if !pm.addr.IsValid() && n == 0 {
118			return components.Status{Text: "Resolving " + host + "...", Activity: true}
119		}
120		where := host
121		if pm.addr.IsValid() && pm.addr.String() != host {
122			where += " (" + pm.addr.String() + ")"
123		}
124		noun := "hops"
125		if n == 1 {
126			noun = "hop"
127		}
128		return components.Status{
129			Text:     fmt.Sprintf("Tracing %s — %d %s answered", where, n, noun),
130			Activity: true,
131		}
132	}
133	
134	// headerInfo lists the target and, once a run ended, how it ended.
135	func (pm *PathModel) headerInfo() []shortcut.HeaderInfo {
136		var out []shortcut.HeaderInfo
137		if !pm.source.isHost() {
138			out = append(out, shortcut.HeaderInfo{Key: "Source", Value: pm.source.Name, Style: theme.HeaderValueStyle})
139		}
140		if pm.target.Host != "" {
141			value := pm.target.String()
142			if pm.addr.IsValid() && pm.addr.String() != pm.target.Host {
143				value += " (" + pm.addr.String() + ")"
144			}
145			out = append(out, shortcut.HeaderInfo{Key: "Target", Value: value, Style: theme.HeaderValueStyle})
146		}
147		if pm.result != nil {
148			out = append(out, shortcut.HeaderInfo{Key: "Path", Value: pathOutcomeLabel(*pm.result), Style: theme.HeaderValueStyle})
149		}
150		return out
151	}
152	
153	// shortcuts: the running mode replaces the list, the other states grey out
154	// (Rule 130).
155	func (pm *PathModel) shortcuts() shortcut.Shortcuts {
156		if pm.pickerOpen() { // a mode: the list is replaced
157			return shortcut.Shortcuts{
158				{Key: "enter", Description: "Trace from it"},
159				{Key: "esc", Description: "Close"},
160			}
161		}
162		off := !pm.launchable().Enabled()
163		source := shortcut.Shortcut{Key: pathSourceKey, Description: "Trace from…", Disabled: !pm.sourceChoosable().Enabled()}
164		switch pm.state {
165		case pathRunning:
166			return shortcut.Shortcuts{{Key: "esc", Description: "Cancel the trace"}}
167		case pathDone:
168			return shortcut.Shortcuts{
169				{Key: "tab", Description: "Switch tab"},
170				{Key: "enter", Description: "Trace again", Disabled: off},
171				source,
172				{Key: "esc", Description: "Edit the target"},
173				{Key: "?", Description: "Help"},
174			}
175		}
176		return shortcut.Shortcuts{
177			{Key: "tab", Description: "Switch tab"},
178			{Key: "enter", Description: "Trace the path", Disabled: off},
179			source,
180		}
181	}
